def _collect_run_ids(package: AuditPackage) -> list[str]:
    values: list[str] = []
    for value in (package.manifest, package.run):
        run_id = _top_level_run_id(value)
        if run_id is not None:
            values.append(run_id)
    for value in (package.timeline, package.decisions, package.evaluations, package.regressions):
        values.extend(_record_list_run_ids(value))
    return values

