def _record_list_run_ids(value: Any) -> list[str]:
    if not isinstance(value, list):
        return []
    run_ids: list[str] = []
    for item in value:
        run_id = _top_level_run_id(item)
        if run_id is not None:
            run_ids.append(run_id)
    return run_ids
